# What distinguishes? In demo2, the zero cells are adjacent to... hmm, actually maybe rule: fill region enclosed; demo2's interior connects to outside through gap at row5 col4? Row5: "1 1 1 0 1 1" -> bottom of box has a gap at col4 which touches exterior zeros (row6 is all zeros). So interior connects to outside -> nothing filled!
def analyze(I,O=None):
    H,W=len(I),len(I[0])
    from collections import deque
    seen=[[False]*W for _ in range(H)]
    comps=[]
    for i in range(H):
        for j in range(W):
            if I[i][j]==1 and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and I[ny][nx]==1 and not seen[ny][nx]:
                                seen[ny][nx]=True; st.append((ny,nx))
                comps.append(cells)
    res=[]
    for cells in comps:
        ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
        y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
        inner=[(i,j) for i in range(y0+1,y1) for j in range(x0+1,x1)]
        # flood from inner zeros, 8-conn, over zeros, see if it hits grid border or exits bbox
        outer=set()
        q=deque([p for p in inner if I[p[0]][p[1]]==0])
        leaked=False
        while q:
            y,x=q.popleft()
            if y==0 or y==H-1 or x==0 or x==W-1: leaked=True
            if I[y][x]!=0 or (y,x) in outer: continue
            outer.add((y,x))
            for dy in(-1,0,1):
                for dx in(-1,0,1):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and I[ny][nx]==0 and (ny,nx) not in outer:
                        q.append((ny,nx))
        res.append((len(cells),(y0,y1,x0,x1),leaked))
    return res
