import numpy as np
def hole_fg(g):
    # flood-fill connected (4-conn) nonzero cells from any nonzero pixel on the border; unreached = holes
    a=np.array(g); H,W=a.shape
    src=[]
    for rr in range(H):
        for c in (0,W-1): src.append((rr,c))
    for cc in range(W):
        for r in (0,H-1): src.append((r,cc))
    lab=[False]*len(src)
    seen=set()
    from collections import deque
    dq=deque()
    for (y,x) in src:
        if a[y,x]:
            dq.append((y,x)); seen.add((y,x))
    while dq:
        y,x=dq.popleft()
        for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)]:
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and not seen and a[ny,nx]:
                seen.add((ny,nx)); dq.append((ny,nx))
    return (np.array(seen).reshape(H,W)|~np.ones_like(a)).astype(int)
